import{_ as a,H as e,f as t,i as _}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"续写新篇 | 深挖Go语言技术细节","description":"","frontmatter":{},"headers":[],"relativePath":"TonyBai·Go语言第一课/续写新篇-深挖Go语言技术细节.md","filePath":"TonyBai·Go语言第一课/续写新篇-深挖Go语言技术细节.md","lastUpdated":1779817248000}'),i={name:"TonyBai·Go语言第一课/续写新篇-深挖Go语言技术细节.md"};function r(l,o,n,G,p,s){return e(),t("div",null,[...o[0]||(o[0]=[_('<h1 id="续写新篇-深挖go语言技术细节" tabindex="-1">续写新篇 | 深挖Go语言技术细节 <a class="header-anchor" href="#续写新篇-深挖go语言技术细节" aria-label="Permalink to &quot;续写新篇 | 深挖Go语言技术细节&quot;">​</a></h1><p>你好，我是Tony Bai，好久不见。</p><p>时隔3年，我带着《Go语言第一课》的续写篇回来了，感谢你的支持！这3年的时间里，Go语言有了非常多积极的变化。在语言特性上，泛型的加入、range-over-fun的正式化等等都在持续丰富着编程的手段。</p><p>基于此，本次专栏的续写，我会从两方面着手。首先，我会从完善知识体系的角度，补充一些专栏中未深入讲解的内容，继续深挖Go语言的技术细节，包括Go测试、Go构建相关细节、Go语言I/O模型与操作等等。然后，我会聚焦这三年来Go语言的新版本、新特性，与你聊聊这些更新对Go语言的发展有什么积极意义，我们该做什么、怎么做，让你掌握主动权。</p><p>目前拟定了这几个话题（以实际上线为准）：</p><ul><li>Go测试的5个实⽤建议</li><li>⼀个Go纯计算逻辑调优的故事</li><li>玩转Go语言I/O：Reader与Writer的使用技巧</li><li>Go语言进化之路：1.19到1.24版本新特性全景回顾</li><li>Go语言几个鲜为人知的细节</li></ul><p>如果你有更多想要了解的内容，也欢迎在留言区告诉我！</p>',7)])])}const f=a(i,[["render",r]]);export{c as __pageData,f as default};
